from pathlib import Path
import ast,json,hashlib
root=Path('/workspace'); p=json.loads((root/'proposal.json').read_text()); r=json.load(open('/tmp/research_runtime.json'))
def validate(value,schema,path='study'):
 typ=schema.get('type')
 types={'object':dict,'array':list,'string':str,'boolean':bool}
 if typ in types: assert isinstance(value,types[typ]),(path,'type',typ)
 if 'const' in schema: assert value==schema['const'],(path,'const')
 if 'enum' in schema: assert value in schema['enum'],(path,'enum')
 if isinstance(value,dict):
  assert all(k in value for k in schema.get('required',[])),(path,'missing required')
  props=schema.get('properties',{})
  if schema.get('additionalProperties') is False: assert not set(value)-set(props),(path,'extra properties')
  for k,v in value.items():
   if k in props: validate(v,props[k],path+'.'+k)
 if isinstance(value,list):
  assert len(value)>=schema.get('minItems',0),(path,'minItems')
  for i,v in enumerate(value): validate(v,schema.get('items',{}),path+f'[{i}]')
 if isinstance(value,str): assert len(value)>=schema.get('minLength',0),(path,'minLength')
validate(p['study'],r['study_schema'])
allowed=set(r['context']['allowed_observation_ids'])
assert p['parent_trial'] in allowed
assert set(p['study']['evidence_refs'])<=allowed
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert 1<=len(p['variants'])<=4
assert any(v['role']=='candidate' for v in p['variants'])
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert len({v['file'] for v in p['variants']})==len(p['variants'])
permitted={'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo'}
for v in p['variants']:
 assert Path(v['file']).name==v['file'] and v['file'].endswith('.py')
 source=(root/v['file']).read_text(); tree=ast.parse(source); compile(source,v['file'],'exec')
 for node in ast.walk(tree):
  if isinstance(node,ast.Import): assert all(n.name.split('.')[0] in permitted for n in node.names)
  if isinstance(node,ast.ImportFrom): assert node.module.split('.')[0] in permitted
  if isinstance(node,ast.Call) and isinstance(node.func,ast.Name): assert node.func.id not in {'open','exec','eval','compile','__import__'}
 config=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
 assert config==v['config']
 assert hashlib.sha256(source.encode()).hexdigest() in v['note']
 # The four standalone modules must differ only in the two literal CONFIG controls.
 normalized=source.replace(f\"'uniform_match': {config['uniform_match']},\",\"'uniform_match': FLAG,\").replace(f\"'rotate_match': {config['rotate_match']},\",\"'rotate_match': FLAG,\")
 if v is p['variants'][0]: normalized_parent=normalized
 else: assert normalized==normalized_parent
for f,expected in [('baseline_reference.py','f4b473cbacf60d72cff90f3721ad754dd617ee6065fe3fca2fc9cd4be2b25c36'),('history_g1_r0004_match_terminal_only.py','a330564ff642ea0eec4e9d7a967cc21754f260e04941acb787c02b9bfed6fde0')]:
 assert hashlib.sha256((root/f).read_bytes()).hexdigest()==expected
print('PASS: full supplied study schema; legal evidence/parent/protocol references; four unique standalone variant configs; syntax; permitted imports; source hash bindings; only two CONFIG flags differ across variants; immutable reference hashes intact.')
print('UNRUN: torch forward/backward, gradient parity, GPU cost, training and validation. Torch is absent; these remain host preflight/execution requirements.')
PY"

